alter table public.users add column if not exists is_officer boolean not null default false;
create table if not exists public.executive_meetings (id bigint generated by default as identity primary key,title text not null,description text not null default '',start_at timestamptz not null,created_by bigint not null references public.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.executive_notes (id bigint generated by default as identity primary key,title text not null,content text not null,created_by bigint not null references public.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.executive_credentials (id bigint generated by default as identity primary key,label text not null,username text not null default '',password_ciphertext text not null,password_iv text not null,created_by bigint not null references public.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.executive_meetings enable row level security;
alter table public.executive_notes enable row level security;
alter table public.executive_credentials enable row level security;
revoke all on public.executive_meetings,public.executive_notes,public.executive_credentials from anon,authenticated;
grant select,insert,update,delete on public.executive_meetings,public.executive_notes,public.executive_credentials to service_role;
grant usage,select on sequence public.executive_meetings_id_seq,public.executive_notes_id_seq,public.executive_credentials_id_seq to service_role;
create or replace function private.is_officer() returns boolean language sql stable security definer set search_path='' as $$ select coalesce((select exists(select 1 from public.users u where u.auth_user_id=(select auth.uid()) and u.status='approved' and (u.role='admin' or u.is_officer))),false) $$;
revoke all on function private.is_officer() from public,anon;
grant execute on function private.is_officer() to authenticated;
drop policy if exists kfc_group_broadcast_receive on realtime.messages;
create policy kfc_group_broadcast_receive on realtime.messages for select to authenticated using ((topic='kfc-executive' and (select private.is_officer())) or case when topic ~ '^kfc-group:[0-9]+$' then (select private.can_access_group(split_part(topic,':',2)::bigint)) else false end);
drop policy if exists kfc_group_broadcast_send on realtime.messages;
create policy kfc_group_broadcast_send on realtime.messages for insert to authenticated with check ((topic='kfc-executive' and (select private.is_officer())) or case when topic ~ '^kfc-group:[0-9]+$' then (select private.can_access_group(split_part(topic,':',2)::bigint)) else false end);

